"; // real live zone bytes, baked in for this browser demo

const $ = id => document.getElementById(id);
function esc(s) { return String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",""":"&quot;"}[c])); }

function hex(buf) { return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2,"0")).join(""); }
function parseZone(text) {
  const names = {};
  for (const line of text.split("
")) {
    const m = line.match(/^\s*([a-z0-9-]+)\.harz\.\s+3600\s+IN\s+TXT\s+"(.*)"\s*$/);
    if (!m) continue;
    try { const v = JSON.parse(m[2].replace(/\(.)/g, "$1")); names[m[1]] = { url: v.url || null, note: v.note || "" }; } catch (e) {}
  }
  return names;
}

(async () => {
  const bytes = new TextEncoder().encode(ZONE_TEXT);
  const digest = hex(await crypto.subtle.digest("SHA-256", bytes));
  const ok = digest === PINNED;
  const names = ok ? parseZone(ZONE_TEXT) : {};
  const list = Object.keys(names).sort();
  const live = list.filter(n => names[n].url && names[n].url.startsWith("https://"));
  const st = $("status");
  $("fp").textContent = "ZSK 86a507a42df64df2";
  if (!ok) {
    st.className = "status bad";
    st.innerHTML = '<div class="row"><span class="k">ZONE REFUSED — hash ' + digest.slice(0,12) + '</span></div>';
    return;
  }
  st.className = "status ok";
  st.innerHTML =
    '<div class="row"><span class="k">Zone</span><span class="v">VERIFIED · height 1</span></div>' +
    '<div class="row"><span class="k">Hash</span><span class="v">' + digest.slice(0,16) + '…f05</span></div>' +
    '<div class="row"><span class="k">Names</span><span class="v">' + list.length + ' (' + live.length + ' live · ' + (list.length-live.length) + ' reserved)</span></div>' +
    '<div class="row"><span class="k">Updated</span><span class="v">live fetch at build time</span></div>';
  const wrap = $("names");
  for (const n of list) {
    const rec = names[n];
    const div = document.createElement("div");
    div.className = "name";
    const isLive = rec.url && rec.url.startsWith("https://");
    div.innerHTML = '<span class="n">' + esc(n) + '.harz</span><span class="tag ' + (isLive ? "live" : "reserved") + '">' + (isLive ? "LIVE" : "RESERVED") + '</span>';
    div.onclick = () => window.open(rec.url || ("https://" + n + ".harz/"), "_blank");
    wrap.appendChild(div);
  }
})();

